#!/usr/bin/env bash
# Droit à l'image : contenus des pages (tous publics) ; un refus d'une personne taguée bloque et masque.
# Prérequis : apply-docs-tags-destinations.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-tags-pages.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/mediaPeople/publicContentRights.service.ts" 2>/dev/null | grep -qF "export async function assertPublicContentRights"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "## Destinations, blocages et masquage" "apps/web/content/docs/dev/legal/tags-de-personnes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-tags-destinations.sh puis apply-docs-tags-destinations.sh"; exit 1; }
MODIFIED=("apps/web/src/features/admin/media-people/RightsCheckBanner.tsx" "apps/web/src/features/page-builder/PageBuilder.tsx" "apps/web/src/features/page-builder/PageRenderer.tsx" "e2e/data.mjs" "e2e/prepare.mjs" "packages/backend/src/modules/courses/router.ts" "packages/backend/src/modules/disciplines/router.ts" "packages/backend/src/modules/events/router.ts" "packages/backend/src/modules/posts/router.ts" "packages/backend/src/modules/seminars/router.ts" "packages/backend/src/modules/sitePages/router.ts" "packages/backend/src/modules/users/router.ts")
CREATED=("e2e/droit-a-l-image-pages.spec.ts" "packages/backend/src/modules/mediaPeople/publicContentRights.service.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export async function assertPublicContentRights" "packages/backend/src/modules/mediaPeople/publicContentRights.service.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

